// Import of required libraries
import { test, expect, SkyrampClient } from '@skyramp/skyramp';
import { get_roles } from './skyrampUtils';

// contract test for /ghost/api/admin/roles/ GET
test('testRolesGet', async () => {
    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Ghost " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Execute Request
    const rolesGetResponse = await get_roles(client, headers);

    // Generated Assertions
    expect(rolesGetResponse.statusCode, 'status code').toBe(200);

    const assignableRoles = JSON.parse((rolesGetResponse as any).responseBody).roles;
    expect(Array.isArray(assignableRoles), 'roles is an array').toBe(true);
    expect(assignableRoles.length, 'assignable roles are returned').toBeGreaterThan(0);

    const roleNames = assignableRoles.map((role: {name: string}) => role.name);

    expect(roleNames, 'Owner is never offered as an assignable role').not.toContain("Owner");

    expect(roleNames, 'Editor Plus is offered as an assignable role').toContain("Editor Plus");

    const editorPlusRole = assignableRoles.find((role: {name: string}) => role.name === "Editor Plus");
    expect(editorPlusRole.description, 'description').toBe("Editors with extended publishing privileges");
    expect(editorPlusRole.id, 'id').toMatch(/^[0-9a-f]{24}$/i);
    expect(editorPlusRole.created_at, 'created_at').toMatch(/^\d{4}-\d{2}-\d{2}T/);
    expect(editorPlusRole.updated_at, 'updated_at').toMatch(/^\d{4}-\d{2}-\d{2}T/);
});
